"""HTTP routes for publishing through WoopSocial.

Mirrors server/uploadpost_api.py: same route shapes, same rules, same
`clip_publishes` table underneath, so the renderer talks to whichever
provider is switched on without caring which it is. Installed with one call
from create_app().

The two rules that hold everywhere here:

* A switched-off feature 404s and /woopsocial/status says only
  `{"enabled": false}`. Off should read as absent.
* **The API key never leaves the backend.** The UI gets `has_key` and four
  characters. Errors go through redact().
"""

from pathlib import Path

from fastapi import HTTPException
from pydantic import BaseModel

from publish.errors import PublishError
from server import woopsocial_service as service
from server.feedback import redact


class KeyIn(BaseModel):
    api_key: str


class SettingsIn(BaseModel):
    enabled: bool | None = None
    platforms: list[str] | None = None
    common_description: str | None = None
    affiliate_url: str | None = None


class ConnectIn(BaseModel):
    platform: str = ""


class BatchIn(BaseModel):
    clip_ids: list[int] = []
    platforms: list[str] = []
    overrides: dict[str, dict] = {}
    # Hours between posts. 24 is one a day, which is the usual shape for
    # spreading a video's clips across a month.
    every_hours: float = 0
    start_at: str = ""
    # Added to every clip in the run, on top of whatever tags each clip
    # already carries. The "#" is optional; duplicates are dropped.
    hashtags: list[str] = []
    # Clip id -> platforms to hold it back from. Absent means every clip
    # goes to every platform picked, which is the usual case; this is for
    # the handful a stricter platform should not get.
    exclude: dict[str, list[str]] = {}
    # A daily budget, which is the shape posting limits actually take:
    # WoopSocial allows five YouTube posts a day. per_day 0 keeps the old
    # flat every_hours behaviour for anything already calling it.
    per_day: int = 0
    gap_hours: float = 1


class PublishIn(BaseModel):
    platforms: list[str] = []
    title: str = ""
    description: str = ""
    tags: list[str] = []
    overrides: dict[str, dict] = {}
    scheduled_date: str = ""


def install(app, *, config, db, data_dir, publish_worker=None) -> None:
    data_path = Path(data_dir)

    def _guard(d):
        if not service.is_enabled(d):
            raise HTTPException(404, "WoopSocial publishing is not enabled")

    def _fail(e: Exception) -> HTTPException:
        message = e.message if isinstance(e, PublishError) else str(e)
        return HTTPException(400, redact(message)[:500])

    def _client():
        if not service.has_key(data_path):
            raise HTTPException(400, "No WoopSocial API key is set.")
        return service.make_client(data_path)

    def _project(d, client) -> str:
        """The project id, created on first use.

        Their accounts hang off a project, and a creator should never be
        asked to make one — so if none is remembered, an existing one is
        adopted or a new one is created under a fixed name.
        """
        settings = service.load_settings(d)
        existing = settings.get("project_id") or ""
        if existing:
            return existing
        projects = client.projects()
        if projects:
            found = str(projects[0].get("id") or "")
        else:
            found = str((client.create_project(service.DEFAULT_PROJECT_NAME) or {}).get("id") or "")
        if found:
            service.save_settings(d, {"project_id": found})
        return found

    # ---- status and settings --------------------------------------------

    @app.get("/woopsocial/status")
    def woopsocial_status():
        d = db()
        try:
            return service.status_payload(d, data_path)
        finally:
            d.close()

    @app.patch("/woopsocial/settings")
    def woopsocial_settings(body: SettingsIn):
        d = db()
        try:
            service.save_settings(
                d, {k: v for k, v in body.model_dump().items() if v is not None}
            )
            return service.status_payload(d, data_path)
        finally:
            d.close()

    # ---- the key ---------------------------------------------------------

    @app.put("/woopsocial/key")
    def put_key(body: KeyIn):
        key = (body.api_key or "").strip()
        if not key:
            raise HTTPException(400, "Enter your WoopSocial API key.")
        service.save_key(data_path, key)
        d = db()
        try:
            try:
                account = service.make_client(data_path).validate_key()
            except PublishError as e:
                # A key that does not work is discarded rather than left
                # making the card claim a connection that is not there.
                service.wipe_key(data_path)
                raise _fail(e) from e
            return {
                **service.status_payload(d, data_path),
                "projects": len(account.get("projects") or []),
            }
        finally:
            d.close()

    @app.delete("/woopsocial/key")
    def delete_key():
        removed = service.wipe_key(data_path)
        d = db()
        try:
            return {"removed": removed, **service.status_payload(d, data_path)}
        finally:
            d.close()

    # ---- social accounts -------------------------------------------------

    @app.get("/woopsocial/connections")
    def connections():
        d = db()
        try:
            _guard(d)
            client = _client()
            try:
                return {"connected": client.connected_platforms(_project(d, client))}
            except PublishError as e:
                raise _fail(e) from e
        finally:
            d.close()

    @app.post("/woopsocial/connect")
    def connect(body: ConnectIn):
        """A browser link for connecting one platform.

        Unlike Upload-Post's single hosted page, WoopSocial authorises one
        platform at a time, so the caller names which.
        """
        d = db()
        try:
            _guard(d)
            if not body.platform:
                raise HTTPException(400, "Which platform?")
            client = _client()
            try:
                url = client.connect_url(_project(d, client), body.platform)
            except PublishError as e:
                raise _fail(e) from e
            if not url:
                raise HTTPException(
                    400, "WoopSocial did not return a connection link. Try again."
                )
            return {"url": url, "platform": body.platform}
        finally:
            d.close()

    # ---- publishing ------------------------------------------------------

    @app.post("/woopsocial/clips/{clip_id}/publish")
    def publish_clip(clip_id: int, body: PublishIn):
        from publish.uploadpost import validate_schedule
        from publish.woopsocial import WoopSocialPublisher

        d = db()
        try:
            _guard(d)
            clip = d.get_clip(clip_id)
            if clip is None:
                raise HTTPException(404, "no such clip")
            if not body.title.strip():
                raise HTTPException(400, "A title is required.")
            if not body.platforms:
                raise HTTPException(400, "Pick at least one platform.")
            if not (clip["path"] and Path(clip["path"]).exists()):
                raise HTTPException(
                    400, "This clip has no rendered file yet. Apply your edits first."
                )

            settings = service.load_settings(d)
            text = body.description
            standing = (settings.get("common_description") or "").strip()
            if standing:
                text = f"{text}\n\n{standing}".strip()
            if body.tags:
                text = f"{text}\n\n{' '.join('#' + t.lstrip('#') for t in body.tags)}".strip()

            try:
                when = validate_schedule(body.scheduled_date)
            except PublishError as e:
                raise _fail(e) from e

            client = _client()
            publisher = WoopSocialPublisher(client, _project(d, client))
            try:
                result = publisher.start(
                    Path(clip["path"]),
                    platforms=body.platforms,
                    title=body.title.strip(),
                    text=text,
                    scheduled_for=when,
                    overrides=body.overrides,
                )
            except PublishError as e:
                raise _fail(e) from e

            _record(d, clip_id, clip, result)
            service.save_settings(d, {"platforms": body.platforms})
            return _payload(d, clip_id, result.request_id)
        finally:
            d.close()

    @app.post("/woopsocial/batch/plan")
    def plan_batch(body: BatchIn):
        """Work out what a batch WOULD do. Creates and publishes nothing.

        This is the half of batch publishing the assistant is allowed to
        call. It resolves the clips, the platforms and the exact time each
        post would land, and hands that back for a person to look at and
        agree to — the same shape as /publish/plan for YouTube, and for the
        same reason: an upload cannot be taken back, so a model may describe
        one but never start one.
        """
        from datetime import datetime, timedelta
        from datetime import timezone as tz

        d = db()
        try:
            _guard(d)
            clip_ids = list(body.clip_ids)
            if not clip_ids:
                raise HTTPException(400, "No clips were chosen.")
            platforms = body.platforms or ["youtube"]

            start = datetime.now(tz.utc) + timedelta(minutes=2)
            if body.start_at:
                try:
                    start = datetime.fromisoformat(body.start_at.replace("Z", "+00:00"))
                except ValueError as e:
                    raise HTTPException(400, "That start time could not be read.") from e

            items, warnings = [], []
            for index, clip_id in enumerate(clip_ids):
                clip = d.get_clip(clip_id)
                if clip is None:
                    warnings.append(f"Clip {clip_id} no longer exists.")
                    continue
                if not (clip["path"] and Path(clip["path"]).exists()):
                    warnings.append(f"Clip {clip_id} has not been rendered yet.")
                    continue
                at = start + timedelta(hours=body.every_hours * index)
                items.append(
                    {
                        "clip_id": clip_id,
                        "title": (clip["title"] or clip["hook"] or f"Clip {clip_id}").strip(),
                        "publish_at": at.isoformat() if body.every_hours or body.start_at else "",
                    }
                )
            if body.per_day:
                # The same slots publish_clips will use, so the plan a person
                # agrees to is the schedule that is sent.
                slots = service.schedule_times(
                    d, len(items), per_day=body.per_day, gap_hours=body.gap_hours,
                    start_at=body.start_at,
                )
                for item, when in zip(items, slots, strict=False):
                    item["publish_at"] = when

            connected: list[str] = []
            try:
                client = _client()
                connected = client.connected_platforms(_project(d, client))
            except (HTTPException, PublishError):
                # Worth planning anyway — the person may be about to connect.
                warnings.append("Could not check which accounts are connected.")
            if connected:
                for p in platforms:
                    if p not in connected:
                        warnings.append(f"{p} is not connected yet and would be skipped.")

            return {
                "provider": "woopsocial",
                "platforms": platforms,
                "every_hours": body.every_hours,
                "per_day": body.per_day,
                "gap_hours": body.gap_hours,
                "hashtags": [h.lstrip("#").strip() for h in body.hashtags if h.strip()],
                "items": items,
                "warnings": warnings,
            }
        finally:
            d.close()

    @app.post("/woopsocial/batch")
    def publish_batch(body: BatchIn):
        """Publish several clips, spaced out over time.

        The loop itself lives in woopsocial_service.publish_clips, because the
        worker needs the same behaviour when a job was queued with "publish
        when done" (server/jobs.py). Two copies would drift.
        """
        from publish.uploadpost import validate_schedule

        if not body.clip_ids:
            raise HTTPException(400, "No clips were chosen.")
        if not body.platforms:
            raise HTTPException(400, "Pick at least one platform.")
        if body.start_at:
            try:
                validate_schedule(body.start_at)
            except PublishError as e:
                raise _fail(e) from e

        d = db()
        try:
            _guard(d)
            try:
                return service.publish_clips(
                    d,
                    data_path,
                    clip_ids=body.clip_ids,
                    platforms=body.platforms,
                    hashtags=body.hashtags,
                    every_hours=body.every_hours,
                    start_at=body.start_at,
                    overrides=body.overrides,
                    exclude=body.exclude,
                    per_day=body.per_day,
                    gap_hours=body.gap_hours,
                )
            except PublishError as e:
                raise _fail(e) from e
        finally:
            d.close()

    def _tags_of(clip) -> list[str]:
        """A clip's hashtags, stored as a JSON list in one column."""
        import json

        raw = clip["hashtags"] if "hashtags" in clip.keys() else ""
        if not raw:
            return []
        try:
            parsed = json.loads(raw)
        except (TypeError, ValueError):
            return []
        if not isinstance(parsed, list):
            return []
        return [str(t).lstrip("#") for t in parsed if str(t).strip()]

    @app.post("/woopsocial/refresh")
    def refresh_all():
        """Catch up on every publish still in the air.

        A batch is accepted in one go and then delivered at WoopSocial's own
        pace, so without this the rows stay at "processing" and there is no
        way to tell a slow queue from a failure.
        """
        d = db()
        try:
            _guard(d)
            try:
                return service.refresh_in_flight(d, data_path)
            except PublishError as e:
                raise _fail(e) from e
        finally:
            d.close()

    @app.get("/woopsocial/schedule")
    def schedule():
        """Everything with a time on it, soonest first."""
        d = db()
        try:
            _guard(d)
            return {"posts": service.upcoming(d)}
        finally:
            d.close()

    @app.get("/woopsocial/in-flight")
    def in_flight_count():
        """How much is still unfinished, without asking WoopSocial."""
        d = db()
        try:
            return {"request_ids": service.in_flight(d)}
        finally:
            d.close()

    @app.post("/woopsocial/refresh/{post_id}")
    def refresh(post_id: str):
        from publish.woopsocial import WoopSocialPublisher

        d = db()
        try:
            _guard(d)
            rows = d.publishes_for_request(post_id)
            if not rows:
                raise HTTPException(404, "no such publish")
            clip_id = int(rows[0]["clip_id"])
            clip = d.get_clip(clip_id)
            client = _client()
            publisher = WoopSocialPublisher(client, _project(d, client))
            try:
                result = publisher.check(post_id)
            except PublishError as e:
                raise _fail(e) from e
            if result.outcomes:
                _record(d, clip_id, clip, result)
            return _payload(d, clip_id, post_id)
        finally:
            d.close()

    def _record(d, clip_id: int, clip, result) -> None:
        for outcome in result.outcomes:
            d.record_clip_publish(
                clip_id,
                outcome.platform,
                {
                    "provider": "woopsocial",
                    "video_id": (clip["video_id"] if clip is not None else "") or "",
                    "start_s": (clip["start_s"] if clip is not None else 0) or 0,
                    "end_s": (clip["end_s"] if clip is not None else 0) or 0,
                    "state": outcome.state,
                    "post_id": outcome.post_id,
                    "post_url": outcome.post_url,
                    "error": outcome.error,
                    "request_id": result.request_id,
                },
            )

    def _payload(d, clip_id: int, request_id: str) -> dict:
        rows = [dict(r) for r in d.clip_publishes(clip_id)]
        live = [r for r in rows if r.get("state") in ("queued", "processing")]
        return {
            "clip_id": clip_id,
            "request_id": request_id,
            "platforms": rows,
            "done": not live,
        }

"""The MCP server speaks the protocol correctly and reports the traps.

Everything here runs against a fake engine, so no API, no network and no
heavy import: these run in CI, where numpy and torch do not exist.
"""

import io
import json
import urllib.error

import pytest

from server import mcp


def _send(message: dict) -> dict | None:
    return mcp.handle(message)


def _request(msg_id, method, params=None):
    out = {"jsonrpc": "2.0", "id": msg_id, "method": method}
    if params is not None:
        out["params"] = params
    return out


def test_initialize_agrees_on_the_client_version():
    reply = _send(_request(1, "initialize", {"protocolVersion": "2025-03-26"}))
    assert reply["result"]["protocolVersion"] == "2025-03-26"
    assert reply["result"]["capabilities"]["tools"] == {"listChanged": False}
    assert reply["result"]["serverInfo"]["name"] == "clips-kitty"


def test_initialize_offers_our_version_when_theirs_is_unknown():
    reply = _send(_request(1, "initialize", {"protocolVersion": "1.0.0"}))
    assert reply["result"]["protocolVersion"] == mcp.PROTOCOL_VERSION


def test_a_notification_is_never_answered():
    assert _send({"jsonrpc": "2.0", "method": "notifications/initialized"}) is None


def test_tools_list_is_well_formed():
    tools = _send(_request(2, "tools/list"))["result"]["tools"]
    assert {t["name"] for t in tools} >= {"queue_video", "list_clips", "export_clip"}
    for tool in tools:
        assert tool["inputSchema"]["type"] == "object"
        assert "handler" not in tool  # the callable must never reach the client
        assert tool["description"]


def test_unknown_tool_is_a_protocol_error():
    reply = _send(_request(3, "tools/call", {"name": "nope", "arguments": {}}))
    assert reply["error"]["code"] == mcp.INVALID_PARAMS


def test_unknown_method_is_a_protocol_error():
    assert _send(_request(4, "nonsense"))["error"]["code"] == mcp.METHOD_NOT_FOUND


def test_queueing_reports_a_job_id(monkeypatch):
    monkeypatch.setattr(mcp, "_request", lambda *a, **k: {"job_id": 149})
    reply = _send(_request(5, "tools/call", {
        "name": "queue_video", "arguments": {"url": "https://youtu.be/x"}}))
    assert reply["result"]["isError"] is False
    assert "149" in reply["result"]["content"][0]["text"]


def test_an_already_processed_video_explains_itself(monkeypatch):
    # job_id null is not a failure, and an agent that assumes otherwise will
    # tell the user their video was queued when it was not.
    monkeypatch.setattr(mcp, "_request", lambda *a, **k: {
        "job_id": None, "already_processed": True, "video_id": "abc"})
    reply = _send(_request(6, "tools/call", {
        "name": "queue_video", "arguments": {"url": "https://youtu.be/x"}}))
    text = reply["result"]["content"][0]["text"]
    assert reply["result"]["isError"] is False
    assert "Not queued" in text and "force" in text


def test_no_clips_is_not_confused_with_a_wrong_id(monkeypatch):
    monkeypatch.setattr(mcp, "_request", lambda *a, **k: [])
    reply = _send(_request(7, "tools/call", {
        "name": "list_clips", "arguments": {"video_id": "typo"}}))
    assert "list_videos" in reply["result"]["content"][0]["text"]


def test_a_stopped_engine_is_a_tool_error_not_a_crash(monkeypatch):
    def refuse(*_a, **_k):
        raise urllib.error.URLError("connection refused")

    monkeypatch.setattr(mcp, "_request", refuse)
    reply = _send(_request(8, "tools/call", {"name": "queue_status", "arguments": {}}))
    assert reply["result"]["isError"] is True
    assert "not answering" in reply["result"]["content"][0]["text"]


def test_the_publishing_tools_are_offered():
    tools = _send(_request(20, "tools/list"))["result"]["tools"]
    names = {t["name"] for t in tools}
    assert {"youtube_status", "publish_plan", "publish_plan_execute", "publish_status"} <= names


def test_a_plan_says_plainly_that_nothing_was_uploaded(monkeypatch):
    # An agent reads only this text, so it has to carry the fact that a plan is
    # a proposal and the confirmation step is not optional.
    monkeypatch.setattr(mcp, "_request", lambda *a, **k: {
        "items": [{"clip_id": 1, "title": "One", "publish_at": None},
                  {"clip_id": 2, "title": "Two", "publish_at": "2026-09-18T17:00:00Z"}],
        "warnings": [],
    })
    reply = _send(_request(21, "tools/call", {
        "name": "publish_plan", "arguments": {"clip_ids": [1, 2]}}))
    text = reply["result"]["content"][0]["text"]
    assert "NOTHING has been uploaded" in text
    assert "publish_plan_execute" in text
    assert "clip 1" in text and "clip 2" in text


def test_a_plan_passes_on_the_quota_warning(monkeypatch):
    monkeypatch.setattr(mcp, "_request", lambda *a, **k: {
        "items": [{"clip_id": 1, "title": "One", "publish_at": None}],
        "warnings": ["3 clips, but only 1 uploads left on today's quota."],
    })
    reply = _send(_request(22, "tools/call", {
        "name": "publish_plan", "arguments": {"clip_ids": [1]}}))
    assert "quota" in reply["result"]["content"][0]["text"]


def test_executing_reports_what_was_skipped(monkeypatch):
    monkeypatch.setattr(mcp, "_request", lambda *a, **k: {
        "started": [{"clip_id": 1, "publish_job_id": 9}],
        "skipped": [{"clip_id": 2, "reason": "This clip has no rendered file yet."}],
    })
    reply = _send(_request(23, "tools/call", {
        "name": "publish_plan_execute", "arguments": {"items": [{"clip_id": 1}, {"clip_id": 2}]}}))
    text = reply["result"]["content"][0]["text"]
    assert "Started 1 upload" in text
    assert "clip 2 skipped" in text


def test_executing_nothing_uploads_nothing(monkeypatch):
    def explode(*_a, **_k):
        raise AssertionError("must not call the API with an empty plan")

    monkeypatch.setattr(mcp, "_request", explode)
    reply = _send(_request(24, "tools/call", {
        "name": "publish_plan_execute", "arguments": {"items": []}}))
    assert "nothing was published" in reply["result"]["content"][0]["text"]


def test_youtube_off_tells_the_agent_to_stop_rather_than_improvise(monkeypatch):
    monkeypatch.setattr(mcp, "_request", lambda *a, **k: {"enabled": False})
    reply = _send(_request(25, "tools/call", {"name": "youtube_status", "arguments": {}}))
    text = reply["result"]["content"][0]["text"]
    assert "switched off" in text
    assert "not something to work around" in text


def test_serve_reads_lines_and_writes_one_message_per_line():
    stdin = io.StringIO(
        json.dumps(_request(1, "initialize", {"protocolVersion": "2025-06-18"})) + "\n"
        + json.dumps({"jsonrpc": "2.0", "method": "notifications/initialized"}) + "\n"
        + json.dumps(_request(2, "tools/list")) + "\n"
    )
    stdout = io.StringIO()
    assert mcp.serve(stdin, stdout) == 0
    lines = [ln for ln in stdout.getvalue().split("\n") if ln]
    assert len(lines) == 2  # the notification is not answered
    assert json.loads(lines[0])["id"] == 1
    assert json.loads(lines[1])["result"]["tools"]


def test_bad_json_gets_a_parse_error():
    stdout = io.StringIO()
    mcp.serve(io.StringIO("{not json\n"), stdout)
    assert json.loads(stdout.getvalue())["error"]["code"] == mcp.PARSE_ERROR


def test_the_api_base_can_be_overridden(monkeypatch):
    monkeypatch.setenv("CLIPS_STUDIO_API", "http://127.0.0.1:9999/")
    assert mcp.api_base() == "http://127.0.0.1:9999"


def test_the_box_can_set_the_things_the_panel_has_checkboxes_for(monkeypatch):
    sent = {}
    monkeypatch.setattr(mcp, "_request", lambda m, p, b=None: sent.update({"body": b})
                        or {"job_id": 7})
    mcp.handle(_request(30, "tools/call", {"name": "queue_video", "arguments": {
        "url": "https://youtu.be/x", "captions": False, "long_clips": True,
        "podcast": True}}))
    assert sent["body"]["captions"] is False
    assert sent["body"]["long_clips"] is True
    assert sent["body"]["podcast"] is True


def test_captions_left_alone_are_not_sent_at_all(monkeypatch):
    # The default lives in settings; sending None would override it with nothing.
    sent = {}
    monkeypatch.setattr(mcp, "_request", lambda m, p, b=None: sent.update({"body": b})
                        or {"job_id": 7})
    mcp.handle(_request(31, "tools/call", {
        "name": "queue_video", "arguments": {"url": "https://youtu.be/x"}}))
    assert "captions" not in sent["body"]


def test_longform_becomes_a_mode(monkeypatch):
    sent = {}
    monkeypatch.setattr(mcp, "_request", lambda m, p, b=None: sent.update({"body": b})
                        or {"job_id": 7})
    mcp.handle(_request(32, "tools/call", {"name": "queue_video", "arguments": {
        "url": "https://youtu.be/x", "longform": "highlights"}}))
    assert sent["body"]["longform"] == {"mode": "highlights"}


def test_a_watermark_is_looked_up_by_name(monkeypatch):
    calls = []

    def fake(method, path, body=None):
        calls.append(path)
        if path == "/branding":
            return [{"id": 3, "name": "Main channel"}, {"id": 4, "name": "Alt"}]
        return {"job_id": 7, "_body": body}

    monkeypatch.setattr(mcp, "_request", fake)
    mcp.handle(_request(33, "tools/call", {"name": "queue_video", "arguments": {
        "url": "https://youtu.be/x", "watermark": "main channel"}}))
    assert "/branding" in calls


def test_a_watermark_that_does_not_exist_lists_the_real_ones(monkeypatch):
    # Guessing an id here would brand a whole stream with the wrong logo.
    monkeypatch.setattr(mcp, "_request", lambda m, p, b=None: (
        [{"id": 3, "name": "Main channel"}] if p == "/branding" else {"job_id": 7}))
    reply = mcp.handle(_request(34, "tools/call", {"name": "queue_video", "arguments": {
        "url": "https://youtu.be/x", "watermark": "nope"}}))
    text = reply["result"]["content"][0]["text"]
    assert reply["result"]["isError"] is True
    assert "Main channel" in text


